import math, sys

class SegmentTree:

	def __init__(self, nums, n):
		self.nums = nums
		self.segTree = [0] * (2 * n)
		self.n = n

	def construct_segTree(self):
		n = self.n
		for i in range(n):
			self.segTree[n + i] = self.nums[i]
		for i in range(n - 1, 0, -1):
			self.segTree[i] = math.gcd(self.segTree[i << 1], self.segTree[i << 1 | 1])

	def update(self, pos, val):
		n = self.n
		self.segTree[pos + n] = val
		pos += n
		i = pos
		while i > 1:
			self.segTree[i >> 1] = math.gcd(self.segTree[i], self.segTree[i ^ 1])
			i >>= 1

	def rangeGcdQuery(self, low, high):
		low += n
		high += n
		ans = -1
		while low < high:
			if low & 1:
				if ans == -1:
					ans = self.segTree[low]
				ans = math.gcd(ans, self.segTree[low])
				low += 1
			if high & 1:
				high -= 1
				if ans == -1:
					ans = self.segTree[high]
				ans = math.gcd(ans, self.segTree[high])
			low >>= 1
			high >>= 1
		return ans

class Solution:

	def findSmallestSubArr(self, nums, n, g):
		segT = SegmentTree(nums, n)
		segT.construct_segTree()
		res = 100000007
		for i in range(n):
			if nums[i] % g:
				continue
			low = i
			high = n - 1
			temp = -1
			while low <= high:
				mid = (low + high) // 2
				gcd = segT.rangeGcdQuery(i, mid + 1)
				if gcd > g:
					low = mid + 1
				elif gcd < g:
					high = mid - 1
				else:
					temp = mid
					high = mid - 1
			if temp != -1:
				res = min(res, temp - i + 1)
		return -1 if res == 100000007 else res
